/**
 * 站台容量裁决：将本批候选区间与其他已发布计划的生效区间合并，
 * 按左闭右开扫描每个候选起点的并行停靠数，超过站点容量即记录超卖明细。
 */
private List<Map<String, Object>> findCapacityViolations(DayPlan plan, List<Long> excludePlanIds,
                                                         List<CapacityCandidate> candidates,
                                                         Instant dayStart, Instant dayEnd) {
    List<Map<String, Object>> violations = new ArrayList<>();
    Map<String, List<TimeInterval>> candidateByStation = new LinkedHashMap<>();
    for (CapacityCandidate candidate : candidates) {
        candidateByStation.computeIfAbsent(candidate.stop().stationId(), k -> new ArrayList<>())
                .add(candidate.interval());
    }
    for (CapacityCandidate candidate : candidates) {
        String stationId = candidate.stop().stationId();
        StationConfig config = candidate.config();
        List<EffectiveStationStop> others = planRepo.findEffectiveStationStops(
                plan.opDate(), List.of(stationId), excludePlanIds);
        List<TimeInterval> all = new ArrayList<>();
        for (EffectiveStationStop other : others) {
            all.add(occupancyInterval(other.arrivalUtc(), other.departureUtc(),
                    dayStart, dayEnd));
        }
        List<TimeInterval> sameBatch = candidateByStation.get(stationId);
        Instant checkPoint = candidate.interval().start();
        int concurrentOthers = 0;
        int concurrentBatch = 0;
        String conflictingScheduleKey = null;
        for (TimeInterval interval : all) {
            if (interval.contains(checkPoint)) {
                concurrentOthers++;
            }
        }
        for (int i = 0; i < others.size(); i++) {
            TimeInterval interval = occupancyInterval(others.get(i).arrivalUtc(),
                    others.get(i).departureUtc(), dayStart, dayEnd);
            if (interval.contains(checkPoint)) {
                conflictingScheduleKey = others.get(i).scheduleKey();
                break;
            }
        }
        for (TimeInterval interval : sameBatch) {
            if (interval.contains(checkPoint)) {
                concurrentBatch++;
            }
        }
        int actualConcurrent = concurrentOthers + concurrentBatch;
        if (actualConcurrent > config.platformCapacity()) {
            Map<String, Object> detail = stopViolation("PLATFORM_CAPACITY_EXCEEDED",
                    candidate.stop(), config, "站台容量已满",
                    actualConcurrent, config.platformCapacity(),
                    actualConcurrent - config.platformCapacity());
            detail.put("atUtc", checkPoint.toString());
            if (conflictingScheduleKey != null) {
                detail.put("conflictingScheduleKey", conflictingScheduleKey);
            }
            violations.add(detail);
        }
    }
    return violations;
}

/**
 * 构造站停规则类冲突明细：始终给出站点、列车与实际/要求/差额（分钟或数量），
 * 单端站停（始发/终到）不参与停站时长比较时实际分钟数为 null。
 */
private Map<String, Object> stopViolation(String type, StationStop stop, StationConfig config,
                                          String message, long actualMinutes,
                                          long requiredMinutes, long shortfall) {
    Map<String, Object> detail = new LinkedHashMap<>();
    detail.put("type", type);
    detail.put("stationId", stop.stationId());
    detail.put("trainNo", stop.trainNo());
    detail.put("seq", stop.seq());
    detail.put("arrivalUtc", stop.arrivalUtc() == null ? null : stop.arrivalUtc().toString());
    detail.put("departureUtc",
            stop.departureUtc() == null ? null : stop.departureUtc().toString());
    detail.put("actualMinutes", actualMinutes);
    detail.put("requiredMinutes", requiredMinutes);
    detail.put("shortfallMinutes", shortfall);
    if (config != null) {
        detail.put("stationVersion", config.version());
    }
    detail.put("message", message);
    return detail;
}

